package com.example.eac_backend_project.files;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import com.example.eac_backend_project.repository.UserRepository;
import java.util.*;
@Service @Transactional
public class FileQuotaService {
 private final FileStorageQuotaRepository quotas;private final FileItemRepository items;private final FileSettingsRepository settings;private final UserRepository users;
 public FileQuotaService(FileStorageQuotaRepository quotas,FileItemRepository items,FileSettingsRepository settings,UserRepository users){this.quotas=quotas;this.items=items;this.settings=settings;this.users=users;}
 private void admin(com.example.eac_backend_project.entity.inventory.User user){if(!FileSuiteService.admin(user))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Administrator required");}
 public static long remaining(long limit,long used){return limit==0?Long.MAX_VALUE:limit-used;}
 public long userLimit(Long id,long fallback){return quotas.findByTargetTypeAndTargetId("USER",id).map(FileStorageQuota::getLimitBytes).orElse(fallback);}
 public long remainingFolder(FileItem file){long remaining=Long.MAX_VALUE;Set<Long> seen=new HashSet<>();for(var node=file.getParent();node!=null;node=node.getParent()){if(!seen.add(node.getId()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invalid folder hierarchy");var quota=quotas.findByTargetTypeAndTargetId("FOLDER",node.getId());if(quota.isPresent())remaining=Math.min(remaining,remaining(quota.get().getLimitBytes(),folderUsed(node.getId())));}return remaining;}
 public long folderUsed(Long id){long used=0;Deque<Long> pending=new ArrayDeque<>();pending.add(id);Set<Long> seen=new HashSet<>();while(!pending.isEmpty()){Long next=pending.removeFirst();if(!seen.add(next))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invalid folder hierarchy");for(var child:items.findByParent_Id(next)){if(child.isFolder())pending.add(child.getId());else used+=itemsBytes(child.getId());}}return used;}
 @jakarta.persistence.PersistenceContext private jakarta.persistence.EntityManager entityManager;
 private long itemsBytes(Long id){return entityManager.createQuery("select coalesce(sum(v.sizeBytes),0) from FileVersion v where v.item.id=:id",Long.class).setParameter("id",id).getSingleResult();}
 public List<Map<String,Object>> list(com.example.eac_backend_project.entity.inventory.User user){admin(user);return quotas.findAll().stream().map(q->{String name=q.getTargetType().equals("USER")?users.findById(q.getTargetId()).map(u->u.getName()+" ("+u.getUserName()+")").orElse("Removed account"):items.findById(q.getTargetId()).map(FileItem::getName).orElse("Removed folder");return Map.<String,Object>of("id",q.getId(),"type",q.getTargetType(),"targetId",q.getTargetId(),"name",name,"limitBytes",q.getLimitBytes(),"usedBytes",q.getTargetType().equals("USER")?items.used(q.getTargetId()):folderUsed(q.getTargetId()));}).toList();}
 public List<Map<String,Object>> targets(com.example.eac_backend_project.entity.inventory.User user,String type,String query){admin(user);String q=Objects.toString(query,"").toLowerCase(Locale.ROOT);if("USER".equals(type))return users.findByEnabledTrue().stream().filter(u->(u.getName()+" "+u.getUserName()+" "+u.getEmail()).toLowerCase(Locale.ROOT).contains(q)).limit(50).map(u->Map.<String,Object>of("id",u.getId(),"name",u.getName()+" ("+u.getUserName()+")")).toList();if(!"FOLDER".equals(type))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose account or folder");return items.findAll().stream().filter(f->f.isFolder()&&f.getDeletedAt()==null&&f.getName().toLowerCase(Locale.ROOT).contains(q)).limit(50).map(f->Map.<String,Object>of("id",f.getId(),"name",f.getName()+" · "+f.getOwner().getUserName())).toList();}
 public void set(com.example.eac_backend_project.entity.inventory.User user,String type,Long id,long limit){admin(user);settings.lock().orElseThrow();if(limit<0||limit>10995116277760L||id==null||(!"USER".equals(type)&&!"FOLDER".equals(type)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a valid storage limit");if("USER".equals(type)){if(!users.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Account not found");}else if(!items.findById(id).map(FileItem::isFolder).orElse(false))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Folder not found");var quota=quotas.findByTargetTypeAndTargetId(type,id).orElseGet(FileStorageQuota::new);quota.setTargetType(type);quota.setTargetId(id);quota.setLimitBytes(limit);quotas.saveAndFlush(quota);}
 public void remove(com.example.eac_backend_project.entity.inventory.User user,Long id){admin(user);settings.lock().orElseThrow();quotas.deleteById(id);}
}
